TWComponent.script:
/**----------------------------------------------------NOTES-----------------------------------------------------------------------**/
// From and to dates are STATIC now!!
/**---------------------------------------------------------------------------------------------------------------------------------**/

tw.local.Contract_Details_IO = new tw.object.toolkit.NBEINTT.Contract_Details_IO_3();
tw.local.Contract_Details_IO.CONREFNO = tw.local.contractNumber;
tw.local.Contract_Details_IO.EXTREFNO = tw.local.contractNumber;
tw.local.Contract_Details_IO.USEREFNO = tw.local.odcRequest.ContractCreation.userReference;
tw.local.Contract_Details_IO.OPERATION = tw.local.odcRequest.BasicDetails.operationType.value;
tw.local.Contract_Details_IO.STAG = "FIN";
tw.local.Contract_Details_IO.AMOUNT = String(tw.local.odcRequest.ContractCreation.amount);
tw.local.Contract_Details_IO.VALDT = formatDate( tw.local.odcRequest.ContractCreation.valueDate );
tw.local.Contract_Details_IO.MATDT = formatDate(tw.local.odcRequest.ContractCreation.maturityDate);
tw.local.Contract_Details_IO.TENOR_DAYS = String(tw.local.odcRequest.ContractCreation.tenorDays);
tw.local.Contract_Details_IO.TRANSITDAYS = String(tw.local.odcRequest.ContractCreation.transitDays);
tw.local.Contract_Details_IO.BASDT = formatDate(tw.local.odcRequest.ContractCreation.baseDate);
//From Query <-----------
if( tw.local.BC_Contract != null){
	tw.local.Contract_Details_IO.FROMDATE = tw.local.BC_Contract.FromDate || tw.local.Contract_Details_IO.BASDT;
	tw.local.Contract_Details_IO.TODATE =  tw.local.BC_Contract.Todate || tw.local.Contract_Details_IO.MATDT;
	tw.local.Contract_Details_IO.USRDEFSTATS = tw.local.BC_Contract.USRDEFSTATS || "NORM";
}
//----------------------> 
//tw.local.Contract_Details_IO.BRANCH = String(tw.local.contractNumber.slice(0, 3));
tw.local.Contract_Details_IO.BRANCH = tw.local.odcRequest.FinancialDetailsFO.executionHub.value;
tw.local.Contract_Details_IO.PRODCD = tw.local.odcRequest.ContractCreation.productCode.value;
tw.local.Contract_Details_IO.CURRENCY = tw.local.odcRequest.ContractCreation.currency;
tw.local.Contract_Details_IO.OUTSTAMT = String(tw.local.odcRequest.FinancialDetailsFO.outstandingAmount);
tw.local.Contract_Details_IO.CUSTOMER_ID = tw.local.odcRequest.CustomerInfo.cif;
tw.local.Contract_Details_IO.CCY = tw.local.odcRequest.ContractCreation.currency;
 tw.local.Contract_Details_IO.REBATE_AMT = String(tw.local.odcRequest.FinancialDetailsFO.contractRebateAmnt) || "0"

// tw.local.Contract_Details_IO.VDATECR = "";
// tw.local.Contract_Details_IO.DRVALDT = "";
// tw.local.Contract_Details_IO.ACPFRMDT = "";
// tw.local.Contract_Details_IO.ACPTODT = "";
// tw.local.Contract_Details_IO.LATEVNSEQNO = "";
// tw.local.Contract_Details_IO.ESN = "";
// tw.local.Contract_Details_IO.PURAMT = "";
// tw.local.Contract_Details_IO.LC_CUST = "";
// tw.local.Contract_Details_IO.LCAMOUNT = "";
// tw.local.Contract_Details_IO.LC_LIAB_AMOUNT = "";
// tw.local.Contract_Details_IO.BASE_DATE_CODE = "";
// tw.local.Contract_Details_IO.PRTYTYP = "";
// tw.local.Contract_Details_IO.LMTMONFLG = "";
// tw.local.Contract_Details_IO.COLLCCY = "";
// tw.local.Contract_Details_IO.TFR_COLL_AMT = "";
// tw.local.Contract_Details_IO.LCISSUEDATE = "";
// tw.local.Contract_Details_IO.REIMDYS = "";
// tw.local.Contract_Details_IO.TRANSFERCOLLATFROMLC = "";

/**---------------------------------------------Parties-------------------------------------------------------**/
tw.local.Contract_Details_IO.Contract_Parties = new tw.object.listOf.toolkit.NBEINTT.Contract_Parties_11();
//Drawee
tw.local.Contract_Details_IO.Contract_Parties[0] = new tw.object.toolkit.NBEINTT.Contract_Parties_11();
tw.local.Contract_Details_IO.Contract_Parties[0].PARTLANG = tw.local.odcRequest.Parties.Drawee.Language;
tw.local.Contract_Details_IO.Contract_Parties[0].PARTCTRCOD = tw.local.odcRequest.Parties.Drawee.country;
tw.local.Contract_Details_IO.Contract_Parties[0].PARTREFNO = tw.local.odcRequest.Parties.Drawee.Reference;
tw.local.Contract_Details_IO.Contract_Parties[0].PARTNAM = tw.local.odcRequest.Parties.Drawee.partyName;
tw.local.Contract_Details_IO.Contract_Parties[0].PARTADD1 = tw.local.odcRequest.Parties.Drawee.address1;
tw.local.Contract_Details_IO.Contract_Parties[0].PARTADD2 = tw.local.odcRequest.Parties.Drawee.address2;
tw.local.Contract_Details_IO.Contract_Parties[0].PARTADD3 = tw.local.odcRequest.Parties.Drawee.address3;
tw.local.Contract_Details_IO.Contract_Parties[0].PARTID = tw.local.odcRequest.Parties.Drawee.partyId;
tw.local.Contract_Details_IO.Contract_Parties[0].PARTTYP = "DRAWEE";
// tw.local.Contract_Details_IO.Contract_Parties[0].PARTADD4 = "";
// tw.local.Contract_Details_IO.Contract_Parties[0].ESN = "";

//Drawer
tw.local.Contract_Details_IO.Contract_Parties[1] = new tw.object.toolkit.NBEINTT.Contract_Parties_11();
tw.local.Contract_Details_IO.Contract_Parties[1].PARTLANG = tw.local.odcRequest.Parties.Drawer.Language;
tw.local.Contract_Details_IO.Contract_Parties[1].PARTCTRCOD = tw.local.odcRequest.Parties.Drawer.country;
tw.local.Contract_Details_IO.Contract_Parties[1].PARTREFNO = tw.local.odcRequest.Parties.Drawer.Reference;
tw.local.Contract_Details_IO.Contract_Parties[1].PARTNAM = tw.local.odcRequest.Parties.Drawer.partyName;
tw.local.Contract_Details_IO.Contract_Parties[1].PARTADD1 = tw.local.odcRequest.Parties.Drawer.address1;
tw.local.Contract_Details_IO.Contract_Parties[1].PARTADD2 = tw.local.odcRequest.Parties.Drawer.address2;
tw.local.Contract_Details_IO.Contract_Parties[1].PARTADD3 = tw.local.odcRequest.Parties.Drawer.address3;
tw.local.Contract_Details_IO.Contract_Parties[1].PARTID = tw.local.odcRequest.Parties.Drawee.partyId;
tw.local.Contract_Details_IO.Contract_Parties[1].PARTTYP = "DRAWER";
// tw.local.Contract_Details_IO.Contract_Parties[1].PARTADD4 = "";
// tw.local.Contract_Details_IO.Contract_Parties[1].ESN = "";

//collectingBank
tw.local.Contract_Details_IO.Contract_Parties[2] = new tw.object.toolkit.NBEINTT.Contract_Parties_11();
tw.local.Contract_Details_IO.Contract_Parties[2].PARTLANG = tw.local.odcRequest.Parties.collectingBank.language;
tw.local.Contract_Details_IO.Contract_Parties[2].PARTCTRCOD = tw.local.odcRequest.Parties.collectingBank.country;
tw.local.Contract_Details_IO.Contract_Parties[2].PARTREFNO = tw.local.odcRequest.Parties.collectingBank.reference;
tw.local.Contract_Details_IO.Contract_Parties[2].PARTNAM = tw.local.odcRequest.Parties.collectingBank.name;
tw.local.Contract_Details_IO.Contract_Parties[2].PARTADD1 = tw.local.odcRequest.Parties.collectingBank.address1;
tw.local.Contract_Details_IO.Contract_Parties[2].PARTADD2 = tw.local.odcRequest.Parties.collectingBank.address2;
tw.local.Contract_Details_IO.Contract_Parties[2].PARTADD3 = tw.local.odcRequest.Parties.collectingBank.address3;
tw.local.Contract_Details_IO.Contract_Parties[2].PARTID = tw.local.odcRequest.Parties.collectingBank.id;
tw.local.Contract_Details_IO.Contract_Parties[2].PARTTYP = "COLLECTING BANK";
// tw.local.Contract_Details_IO.Contract_Parties[1].PARTADD4 = "";
// tw.local.Contract_Details_IO.Contract_Parties[2].ESN = "";
tw.local.Contract_Details_IO.Contract_Parties[2].Party_Addr = new tw.object.listOf.toolkit.NBEINTT.Party_Addr_3();
tw.local.Contract_Details_IO.Contract_Parties[2].Party_Addr[0] = new tw.object.toolkit.NBEINTT.Party_Addr_3();
tw.local.Contract_Details_IO.Contract_Parties[2].Party_Addr[0].MEDIA = tw.local.odcRequest.Parties.collectingBank.media;
tw.local.Contract_Details_IO.Contract_Parties[2].Party_Addr[0].ADDR = tw.local.odcRequest.Parties.collectingBank.address;

//Case in need
if (tw.local.odcRequest.Parties.caseInNeed && tw.local.odcRequest.Parties.caseInNeed.partyId) {
	tw.local.Contract_Details_IO.Contract_Parties[3] = new tw.object.toolkit.NBEINTT.Contract_Parties_11();
	tw.local.Contract_Details_IO.Contract_Parties[3].PARTLANG = tw.local.odcRequest.Parties.caseInNeed.language;
	tw.local.Contract_Details_IO.Contract_Parties[3].PARTCTRCOD = tw.local.odcRequest.Parties.caseInNeed.country;
	tw.local.Contract_Details_IO.Contract_Parties[3].PARTREFNO = tw.local.odcRequest.Parties.caseInNeed.refrence;
	tw.local.Contract_Details_IO.Contract_Parties[3].PARTNAM = tw.local.odcRequest.Parties.caseInNeed.partyName;
	tw.local.Contract_Details_IO.Contract_Parties[3].PARTADD1 = tw.local.odcRequest.Parties.caseInNeed.address1;
	tw.local.Contract_Details_IO.Contract_Parties[3].PARTADD2 = tw.local.odcRequest.Parties.caseInNeed.address2;
	tw.local.Contract_Details_IO.Contract_Parties[3].PARTADD3 = tw.local.odcRequest.Parties.caseInNeed.address3;
	tw.local.Contract_Details_IO.Contract_Parties[3].PARTID = tw.local.odcRequest.Parties.caseInNeed.partyId;
	tw.local.Contract_Details_IO.Contract_Parties[3].PARTTYP = "CASE IN NEED";
	// tw.local.Contract_Details_IO.Contract_Parties[1].PARTADD4 = "";
	// tw.local.Contract_Details_IO.Contract_Parties[3].ESN = "";
}

/**---------------------------------------------Charges and Settlements-------------------------------------------------**/
tw.local.Contract_Details_IO.Charges = new tw.object.toolkit.NBEINTT.Charges_28();
tw.local.Contract_Details_IO.Settlements = new tw.object.toolkit.NBEINTT.Settlements_28();
tw.local.Contract_Details_IO.Charges.CONREFNO = tw.local.contractNumber;
tw.local.Contract_Details_IO.Settlements.CONREFNO = tw.local.contractNumber;
// tw.local.Contract_Details_IO.Settlements.LatestVersionSequenceNumber = "";
if (tw.local.odcRequest.ChargesAndCommissions.length > 0) {
	tw.local.Contract_Details_IO.Charges.Charge_Application = new tw.object.listOf.toolkit.NBEINTT.Charge_Application_16();
	tw.local.Contract_Details_IO.Charges.Charge_Association = new tw.object.listOf.toolkit.NBEINTT.Charge_Association_19();
	tw.local.Contract_Details_IO.Settlements.Contract_Settlement = new tw.object.listOf.toolkit.NBEINTT.Contract_Settlement_24();
	var j = 0;
	for (var i = 0; i < tw.local.odcRequest.ChargesAndCommissions.length; i++) {
		tw.local.Contract_Details_IO.Charges.Charge_Application[i] = new tw.object.toolkit.NBEINTT.Charge_Application_16();
		tw.local.Contract_Details_IO.Charges.Charge_Application[i].COMPNT = tw.local.odcRequest.ChargesAndCommissions[i].component;
		tw.local.Contract_Details_IO.Charges.Charge_Application[i].CHRGAMT = String(tw.local.odcRequest.ChargesAndCommissions[i].changeAmount);
		tw.local.Contract_Details_IO.Charges.Charge_Application[i].WAIVER = tw.local.odcRequest.ChargesAndCommissions[i].waiver ? "Y" : "N";
		tw.local.Contract_Details_IO.Charges.Charge_Application[i].CREATESN = "1";
		tw.local.Contract_Details_IO.Charges.Charge_Application[i].CHRGCCY = tw.local.odcRequest.ChargesAndCommissions[i].defaultCurrency.value;
		// tw.local.Contract_Details_IO.Charges.Charge_Application[i].TGCCY = "";

		tw.local.Contract_Details_IO.Charges.Charge_Association[i] = new tw.object.toolkit.NBEINTT.Charge_Association_19();
		tw.local.Contract_Details_IO.Charges.Charge_Association[i].COMPNT = tw.local.odcRequest.ChargesAndCommissions[i].component;
		tw.local.Contract_Details_IO.Charges.Charge_Association[i].CREATESN = "1";
		tw.local.Contract_Details_IO.Charges.Charge_Association[i].WAIVER = tw.local.odcRequest.ChargesAndCommissions[i].waiver ? "Y" : "N";
		if (!tw.local.odcRequest.ChargesAndCommissions[i].waiver) {
			tw.local.Contract_Details_IO.Settlements.Contract_Settlement[j] = new tw.object.toolkit.NBEINTT.Contract_Settlement_24();
			tw.local.Contract_Details_IO.Settlements.Contract_Settlement[j].COMPNT = tw.local.odcRequest.ChargesAndCommissions[i].component;
			tw.local.Contract_Details_IO.Settlements.Contract_Settlement[j].ACCBRN = tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.branchCode;
			tw.local.Contract_Details_IO.Settlements.Contract_Settlement[j].ACCCCY = tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.currency.value;
			tw.local.Contract_Details_IO.Settlements.Contract_Settlement[j].ACC = tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.glAccountNo ? tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.glAccountNo : tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.customerAccountNo;
			tw.local.Contract_Details_IO.Settlements.Contract_Settlement[j].EXRATE = String(tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.standardExRate);
			tw.local.Contract_Details_IO.Settlements.Contract_Settlement[j].NEGOTIATEDRATE = String(tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.negotiatedExRate);
			// tw.local.Contract_Details_IO.Settlements.Contract_Settlement[0].TAGCCY = "";
			// tw.local.Contract_Details_IO.Settlements.Contract_Settlement[0].DRCRIND = "";
			// tw.local.Contract_Details_IO.Settlements.Contract_Settlement[0].ORGEXCHRATE = "";
			j++;
		}
	}
}

/**------------------------------------------------Contract_Multitnr----------------------------------------------------**/
if (tw.local.odcRequest.FinancialDetailsFO.multiTenorDates.length > 0) {
	tw.local.Contract_Details_IO.Contract_Multitnr = new tw.object.listOf.toolkit.NBEINTT.Contract_Multitnr_2();
	for (var i = 0; i < tw.local.odcRequest.FinancialDetailsFO.multiTenorDates.length; i++) {
		tw.local.Contract_Details_IO.Contract_Multitnr[i] = new tw.object.toolkit.NBEINTT.Contract_Multitnr_2();
		tw.local.Contract_Details_IO.Contract_Multitnr[i].SERIALNUM = String(i-1);
		tw.local.Contract_Details_IO.Contract_Multitnr[i].BASDATE = formatDate(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].instalmentBaseDate);
		tw.local.Contract_Details_IO.Contract_Multitnr[i].VALUDATE = formatDate(tw.local.odcRequest.ContractCreation.valueDate);
		tw.local.Contract_Details_IO.Contract_Multitnr[i].TNOR = String(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].instalmentTenorDays);
		tw.local.Contract_Details_IO.Contract_Multitnr[i].MATDAT = formatDate(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].instalmentMaturityDate);
		tw.local.Contract_Details_IO.Contract_Multitnr[i].BILLAMNT = String(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].amount || 0);
		tw.local.Contract_Details_IO.Contract_Multitnr[i].REBATAMT = String(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].splitRebateAmnt || "0") ;
//		 tw.local.Contract_Details_IO.Contract_Multitnr[i].TRANSTDAYS = "";
		// tw.local.Contract_Details_IO.Contract_Multitnr[i].SPLITPCT = "";
		// tw.local.Contract_Details_IO.Contract_Multitnr[i].BASEDATE_CODE = "";
		// tw.local.Contract_Details_IO.Contract_Multitnr[i].DISCOUNTAMT = "";
		// tw.local.Contract_Details_IO.Contract_Multitnr[i].DISCOUNTDAMT = "";
		// tw.local.Contract_Details_IO.Contract_Multitnr[i].LIQDTNAMT = "";
		// tw.local.Contract_Details_IO.Contract_Multitnr[i].LIQDTDAMT = "";
		// tw.local.Contract_Details_IO.Contract_Multitnr[i].FRMCALCDATE = "";
		// tw.local.Contract_Details_IO.Contract_Multitnr[i].TOCALCDATE = "";
		// tw.local.Contract_Details_IO.Contract_Multitnr[i].USRDFNDSTS = "";
	}
}

/**---------------------------------------------Document_Details---------------------------------------------------------------------**/
if( tw.local.BC_Contract && tw.local.BC_Contract.Document_Details &&  tw.local.BC_Contract.Document_Details.listLength > 0 ){
	tw.local.Contract_Details_IO.Document_Details = new tw.object.listOf.toolkit.NBEINTT.Document_Details_11();
	for (var i=0; i<tw.local.BC_Contract.Document_Details.listLength; i++) {
		tw.local.Contract_Details_IO.Document_Details[i] = new tw.object.toolkit.NBEINTT.Document_Details_11();
		tw.local.Contract_Details_IO.Document_Details[i].DOCCD = tw.local.BC_Contract.Document_Details[i].DocCode;
		tw.local.Contract_Details_IO.Document_Details[i].DESC = tw.local.BC_Contract.Document_Details[i].DocDesc;
		// tw.local.Contract_Details_IO.Document_Details[0].FRSTMAILCOP = "";
		// tw.local.Contract_Details_IO.Document_Details[0].FRSTMAILORG = "";
	}
}


/**-----------------------------------------------------------------------------------------------------------------------------------------**/
/**--------------------------------------------------------Contract_Goods_Details-----------------------------------------------------------**/
if (!!tw.local.odcRequest.ContractCreation.HScode && !!tw.local.odcRequest.ContractCreation.HScode.value) {
	tw.local.Contract_Details_IO.Contract_Goods_Details = new tw.object.listOf.toolkit.NBEINTT.Contract_Goods_Details_7();
	tw.local.Contract_Details_IO.Contract_Goods_Details[0] = new tw.object.toolkit.NBEINTT.Contract_Goods_Details_7();
   	tw.local.Contract_Details_IO.Contract_Goods_Details[0].GOODS_CODE = tw.local.odcRequest.ContractCreation.HScode.name ;
   	tw.local.Contract_Details_IO.Contract_Goods_Details[0].GOODS_DESCR = tw.local.odcRequest.ContractCreation.HScode.value;
   	

}
// tw.local.Contract_Details_IO.Contract_Goods_Details = new tw.object.listOf.toolkit.NBEINTT.Contract_Goods_Details_7();
// tw.local.Contract_Details_IO.Contract_Goods_Details[0] = new tw.object.toolkit.NBEINTT.Contract_Goods_Details_7();
// tw.local.Contract_Details_IO.Contract_Goods_Details[0].PRICE_PER_UNIT = "";
// tw.local.Contract_Details_IO.Contract_Goods_Details[0].NO_OF_UNITS = "";
// tw.local.Contract_Details_IO.Contract_Goods_Details[0].GOODS_CODE = "";
// tw.local.Contract_Details_IO.Contract_Goods_Details[0].GOODS_DESCR = "";
/**------------------------------------------------Party_Limits-------------------------------------------------**/
