ns16:scriptTask.ns16:script:
/**----------------------------------------------------NOTES-----------------------------------------------------------------------**/
// From and to dates are STATIC now!!
/**---------------------------------------------------------------------------------------------------------------------------------**/

tw.local.Contract_Details_IO = new tw.object.toolkit.NBEINTT.Contract_Details_IO_3();
tw.local.Contract_Details_IO.CONREFNO = tw.local.contractNumber;
tw.local.Contract_Details_IO.EXTREFNO = tw.local.contractNumber;
tw.local.Contract_Details_IO.USEREFNO = tw.local.odcRequest.ContractCreation.userReference;
tw.local.Contract_Details_IO.OPERATION = tw.local.odcRequest.BasicDetails.operationType.value;
tw.local.Contract_Details_IO.STAG = "FIN";
tw.local.Contract_Details_IO.AMOUNT = String(tw.local.odcRequest.ContractCreation.amount);
tw.local.Contract_Details_IO.VALDT = formatDate( tw.local.odcRequest.ContractCreation.valueDate );
tw.local.Contract_Details_IO.MATDT = formatDate(tw.local.odcRequest.ContractCreation.maturityDate);
tw.local.Contract_Details_IO.TENOR_DAYS = String(tw.local.odcRequest.ContractCreation.tenorDays);
tw.local.Contract_Details_IO.TRANSITDAYS = String(tw.local.odcRequest.ContractCreation.transitDays);
tw.local.Contract_Details_IO.BASDT = formatDate(tw.local.odcRequest.ContractCreation.baseDate);
//From Query <-----------
if( tw.local.BC_Contract != null){
	tw.local.Contract_Details_IO.FROMDATE = tw.local.BC_Contract.FromDate || tw.local.Contract_Details_IO.BASDT;
	tw.local.Contract_Details_IO.TODATE =  tw.local.BC_Contract.Todate || tw.local.Contract_Details_IO.MATDT;
	tw.local.Contract_Details_IO.USRDEFSTATS = tw.local.BC_Contract.USRDEFSTATS || "NORM";
}
//----------------------> 
//tw.local.Contract_Details_IO.BRANCH = String(tw.local.contractNumber.slice(0, 3));
tw.local.Contract_Details_IO.BRANCH = tw.local.odcRequest.FinancialDetailsFO.executionHub.value;
tw.local.Contract_Details_IO.PRODCD = tw.local.odcRequest.ContractCreation.productCode.value;
tw.local.Contract_Details_IO.CURRENCY = tw.local.odcRequest.ContractCreation.currency;
tw.local.Contract_Details_IO.OUTSTAMT = String(tw.local.odcRequest.FinancialDetailsFO.outstandingAmount);
tw.local.Contract_Details_IO.CUSTOMER_ID = tw.local.odcRequest.CustomerInfo.cif;
tw.local.Contract_Details_IO.CCY = tw.local.odcRequest.ContractCreation.currency;
 tw.local.Contract_Details_IO.REBATE_AMT = String(tw.local.odcRequest.FinancialDetailsFO.contractRebateAmnt) || "0"

// tw.local.Contract_Details_IO.VDATECR = "";
// tw.local.Contract_Details_IO.DRVALDT = "";
// tw.local.Contract_Details_IO.ACPFRMDT = "";
